package com.example.qldetai.feature.evaluation;
import com.example.qldetai.aspect.BusinessAudit; import com.example.qldetai.exception.*; import com.example.qldetai.feature.identity.*; import com.example.qldetai.feature.project.*; import com.example.qldetai.feature.topic.TopicSupervisorRepository; import com.example.qldetai.feature.evaluation.EvaluationDtos.*; import java.math.*; import java.time.*; import java.util.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class EvaluationService {
 private final AssessmentComponentRepository components; private final RubricRepository rubrics; private final RubricCriterionRepository criteria; private final EvaluationAssignmentRepository evaluations; private final ScoreSheetRepository sheets; private final ScoreDetailRepository details; private final ProjectAssignmentRepository assignments; private final LecturerRepository lecturers; private final UserRepository users; private final TopicSupervisorRepository supervisors; private final Clock clock;
 public EvaluationService(AssessmentComponentRepository components,RubricRepository rubrics,RubricCriterionRepository criteria,EvaluationAssignmentRepository evaluations,ScoreSheetRepository sheets,ScoreDetailRepository details,ProjectAssignmentRepository assignments,LecturerRepository lecturers,UserRepository users,TopicSupervisorRepository supervisors,Clock clock){this.components=components;this.rubrics=rubrics;this.criteria=criteria;this.evaluations=evaluations;this.sheets=sheets;this.details=details;this.assignments=assignments;this.lecturers=lecturers;this.users=users;this.supervisors=supervisors;this.clock=clock;}
 @Transactional @BusinessAudit(action="RUBRIC_CREATE",entityType="RUBRIC") public RubricResponse createRubric(CreateRubricRequest r,Long actor){manager(actor); AssessmentComponent c=components.findById(r.componentId()).orElseThrow(()->new ResourceNotFoundException("Assessment component was not found.")); Rubric rubric=new Rubric();rubric.setComponent(c);rubric.setName(r.name().trim());rubric.setVersionNo(1);rubric.setCreatedAt(LocalDateTime.now(clock));rubric=rubrics.save(rubric); for(CriterionRequest x:r.criteria()){RubricCriterion z=new RubricCriterion();z.setRubric(rubric);z.setName(x.name().trim());z.setDescription(x.description().trim());z.setMaxScore(x.maxScore());z.setSortOrder(x.sortOrder());criteria.save(z);} return rubric(rubric); }
 @Transactional @BusinessAudit(action="EVALUATION_ASSIGN",entityType="EVALUATION_ASSIGNMENT") public Long assign(CreateEvaluationRequest r,Long actor){manager(actor); ProjectAssignment a=assignments.findById(r.assignmentId()).orElseThrow(()->new ResourceNotFoundException("Project assignment was not found.")); Rubric rubric=rubrics.findById(r.rubricId()).orElseThrow(()->new ResourceNotFoundException("Rubric was not found.")); Lecturer l=lecturers.findById(r.lecturerId()).orElseThrow(()->new ResourceNotFoundException("Lecturer was not found.")); if(!rubric.getComponent().getPeriod().getId().equals(a.getPeriod().getId()))throw new BusinessRuleException("Rubric and assignment must belong to the same period."); if(supervisors.findByTopicIdOrderBySlotNoAsc(a.getTopic().getId()).stream().anyMatch(x->x.getLecturer().getId().equals(l.getId())))throw new BusinessRuleException("A supervisor cannot evaluate their own topic."); if(evaluations.countByAssignmentIdAndComponentIdAndStatus(a.getId(),rubric.getComponent().getId(),EvaluationStatus.ACTIVE)>=rubric.getComponent().getExpectedEvaluators())throw new ConflictException("This component already has enough evaluators."); EvaluationAssignment e=new EvaluationAssignment();e.setAssignment(a);e.setComponent(rubric.getComponent());e.setRubric(rubric);e.setLecturer(l);e.setDeadlineAt(r.deadlineAt());return evaluations.save(e).getId(); }
 @Transactional @BusinessAudit(action="SCORE_SHEET_SAVE",entityType="SCORE_SHEET",entityIdArgument=0) public ScoreSheetResponse saveSheet(Long evaluationId,SaveSheetRequest r,Long actor){EvaluationAssignment e=evaluations.findById(evaluationId).orElseThrow(()->new ResourceNotFoundException("Evaluation assignment was not found.")); if(!e.getLecturer().getUser().getId().equals(actor))throw new AccessDeniedException("Only the assigned evaluator can score this sheet."); ScoreSheet s=sheets.findByEvaluationId(evaluationId).orElseGet(()->{ScoreSheet n=new ScoreSheet();n.setEvaluation(e);n.setRubric(e.getRubric());return n;}); if(s.getStatus()==ScoreSheetStatus.LOCKED)throw new BusinessRuleException("A locked score sheet cannot be edited."); if(s.getId()!=null&&s.getVersion()!=r.version())throw new ConflictException("The score sheet was changed. Reload and try again."); Map<Long,RubricCriterion> allowed=new HashMap<>();criteria.findByRubricIdOrderBySortOrder(e.getRubric().getId()).forEach(x->allowed.put(x.getId(),x)); if(r.scores().size()!=allowed.size())throw new BusinessRuleException("Every rubric criterion must receive a score."); for(ScoreRequest x:r.scores()){RubricCriterion c=allowed.get(x.criterionId());if(c==null||x.score().compareTo(c.getMaxScore())>0)throw new BusinessRuleException("A score must be between zero and its criterion maximum.");} s.setOverallComment(r.overallComment());s.setStatus(r.submit()?ScoreSheetStatus.SUBMITTED:ScoreSheetStatus.DRAFT);if(r.submit())s.setSubmittedAt(LocalDateTime.now(clock));s=sheets.save(s);details.deleteBySheetId(s.getId());for(ScoreRequest x:r.scores()){RubricCriterion c=allowed.get(x.criterionId());ScoreDetail d=new ScoreDetail();d.setSheet(s);d.setCriterion(c);d.setMaxScore(c.getMaxScore());d.setScore(x.score());d.setComment(x.comment());details.save(d);}return sheet(s);}
 @Transactional(readOnly=true) public ScoreSheetResponse mySheet(Long evaluationId,Long actor){EvaluationAssignment e=evaluations.findById(evaluationId).orElseThrow(()->new ResourceNotFoundException("Evaluation assignment was not found."));if(!e.getLecturer().getUser().getId().equals(actor))throw new AccessDeniedException("You cannot view this score sheet.");return sheets.findByEvaluationId(evaluationId).map(this::sheet).orElse(new ScoreSheetResponse(null,evaluationId,ScoreSheetStatus.DRAFT,0,BigDecimal.ZERO,null,List.of()));}
 private void manager(Long id){boolean ok=users.findWithRolesById(id).map(u->u.getUserRoles().stream().anyMatch(x->x.getRole().getCode()==RoleCode.ADMIN||x.getRole().getCode()==RoleCode.LECTURER)).orElse(false);if(!ok)throw new AccessDeniedException("Only lecturers or administrators can manage evaluation.");}
 private RubricResponse rubric(Rubric r){return new RubricResponse(r.getId(),r.getComponent().getId(),r.getName(),r.getVersionNo(),criteria.findByRubricIdOrderBySortOrder(r.getId()).stream().map(x->new CriterionResponse(x.getId(),x.getName(),x.getDescription(),x.getMaxScore(),x.getSortOrder())).toList());}
 private ScoreSheetResponse sheet(ScoreSheet s){List<ScoreRequest> xs=details.findBySheetId(s.getId()).stream().map(d->new ScoreRequest(d.getCriterion().getId(),d.getScore(),d.getComment())).toList();BigDecimal total=xs.stream().map(ScoreRequest::score).reduce(BigDecimal.ZERO,BigDecimal::add);return new ScoreSheetResponse(s.getId(),s.getEvaluation().getId(),s.getStatus(),s.getVersion(),total,s.getOverallComment(),xs);}
}
